files.content:
.root {
  --vt-surface: #ffffff;
  --vt-surface-2: #f0f8ff;
  --vt-surface-deep: #4f83d1;
  --vt-ink: #1c2733;
  --vt-ink-soft: #717275;
  --vt-on-deep: #ffffff;
  --vt-accent: #7cb8eb;
  --vt-on-accent: #ffffff;
  --vt-accent-ink: #4f83d1;
  --vt-accent-on-deep: #dceefb;
  --vt-line: #e9eaeb;
  font-family: 'Nunito Sans', 'Open Sans', sans-serif;
  color: var(--vt-ink);
  background: var(--vt-surface);
  line-height: 1.6;
}

.root :where(a) { color: inherit; text-decoration: none; }
.root :where(button) { font: inherit; cursor: pointer; border: 0; }
.root :where(h1,h2,h3,h4,h5,h6) { margin: 0; color: var(--vt-ink); font-weight: 700; }
.root :where(p) { margin: 0; }
.root :where(ul) { margin: 0; padding: 0; list-style: none; }
.root :where(img) { max-width: 100%; display: block; }

.root a:focus-visible,
.root button:focus-visible {
  outline: 3px solid var(--vt-accent);
  outline-offset: 2px;
}

.container {
  width: min(1120px, calc(100% - 48px));
  margin-inline: auto;
}

.topbar {
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  padding: 10px 0;
}

.topbar .container {
  display: flex;
  align-items: center;
  gap: 24px;
  flex-wrap: wrap;
}

.topbarText {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 14px;
  line-height: 1.3;
}

.topbarPhone {
  margin-left: auto;
  color: var(--vt-on-accent);
  font-weight: 700;
  font-size: 14px;
}

.nav {
  position: absolute;
  top: 44px;
  left: 0;
  right: 0;
  z-index: 20;
  padding: 16px 0;
}

.navIn {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}

.logo {
  display: inline-flex;
  align-items: center;
  color: var(--vt-on-deep);
  font-weight: 700;
  font-size: 1.25rem;
}

.brand { display: inline-flex; }

.navLinks {
  display: flex;
  align-items: center;
  gap: 26px;
}

.navLinks a {
  color: var(--vt-on-deep);
  font-size: 15px;
  font-weight: 600;
  transition: color 0.2s ease;
}

.navLinks a:hover { color: var(--vt-accent-on-deep); }
.navLinks .navCta {
  background: var(--vt-accent-ink);
  border-radius: 999px;
  padding: 10px 20px;
  color: var(--vt-on-accent);
}

.navLinks .navCta:hover { background: var(--vt-accent); color: var(--vt-on-accent); }

.hero {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 86vh;
  padding: 170px 0 140px;
  background-color: var(--vt-surface-deep);
  background-size: cover;
  background-position: center;
  overflow: hidden;
  isolation: isolate;
}

.heroOverlay {
  position: absolute;
  inset: 0;
  background: var(--vt-surface-deep);
  opacity: 0.72;
  z-index: -1;
}

.heroContent {
  position: relative;
  z-index: 2;
  max-width: 820px;
  text-align: center;
  color: var(--vt-on-deep);
}

.heroKicker {
  font-size: 14px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--vt-accent-on-deep);
  margin-bottom: 12px;
}

.heroTitle {
  font-size: clamp(2.9rem, 7vw, 4.6rem);
  line-height: 1.04;
  color: var(--vt-on-deep);
  margin-bottom: 18px;
}

.heroLead {
  color: var(--vt-on-deep);
  font-size: 1.12rem;
  max-width: 620px;
  margin: 0 auto 32px;
  opacity: 0.9;
}

.heroActions {
  display: flex;
  justify-content: center;
  gap: 16px;
  flex-wrap: wrap;
}

.btnPrimary {
  background: var(--vt-accent-ink);
  color: var(--vt-on-accent);
  border-radius: 999px;
  padding: 14px 30px;
  font-weight: 700;
  transition: background 0.2s ease;
}

.btnPrimary:hover { background: var(--vt-accent); color: var(--vt-on-accent); }

.btnGhost {
  border: 2px solid var(--vt-on-deep);
  color: var(--vt-on-deep);
  border-radius: 999px;
  padding: 12px 28px;
  font-weight: 700;
  transition: background 0.2s ease, color 0.2s ease;
}

.btnGhost:hover { background: var(--vt-on-deep); color: var(--vt-accent-ink); }

.wave {
  position: absolute;
  bottom: -1px;
  left: 0;
  width: 100%;
  height: 100px;
  display: block;
  z-index: 3;
}

.wave path { fill: var(--vt-surface); }

.story {
  padding: 90px 0;
  background: var(--vt-surface);
}

.storyGrid {
  display: grid;
  grid-template-columns: 1.05fr 0.95fr;
  gap: 56px;
  align-items: center;
}

.sectionKicker {
  color: var(--vt-accent-ink);
  font-size: 14px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  margin-bottom: 10px;
}

.sectionTitle {
  font-size: clamp(2rem, 4vw, 2.9rem);
  line-height: 1.12;
  color: var(--vt-ink);
  margin-bottom: 20px;
}

.storyIntro { color: var(--vt-ink-soft); font-size: 1.05rem; margin-bottom: 16px; }
.storyParagraph { color: var(--vt-ink-soft); margin-top: 12px; }

.storyMedia { position: relative; }

.storyImage {
  border-radius: 24px;
  width: 100%;
  aspect-ratio: 4 / 3;
  object-fit: cover;
  box-shadow: 0 24px 45px -30px var(--vt-accent-ink);
}

.callCard {
  position: absolute;
  right: -16px;
  bottom: 24px;
  background: var(--vt-accent-ink);
  color: var(--vt-on-accent);
  border-radius: 16px;
  padding: 20px 24px;
  text-align: center;
  box-shadow: 0 18px 35px -22px var(--vt-accent-ink);
}

.callCard strong { display: block; font-size: 14px; margin-bottom: 6px; }
.callCard a { color: var(--vt-on-accent); font-weight: 800; font-size: 1.15rem; }

.services { padding: 90px 0; background: var(--vt-surface-2); }
.sectionHead { max-width: 640px; margin-bottom: 44px; }
.sectionHead .sectionTitle { margin-bottom: 0; }

.servicesGrid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 28px;
}

.serviceCard {
  display: grid;
  grid-template-columns: 220px minmax(0, 1fr);
  background: var(--vt-surface);
  border-radius: 18px;
  overflow: hidden;
  box-shadow: 0 18px 40px -32px var(--vt-accent-ink);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.serviceCard:hover {
  transform: translateY(-4px);
  box-shadow: 0 26px 48px -32px var(--vt-accent-ink);
}

.serviceMedia { background: var(--vt-accent); min-height: 200px; }
.serviceImage { width: 100%; height: 100%; object-fit: cover; }

.serviceInfo { padding: 28px 24px; display: flex; flex-direction: column; gap: 8px; }
.serviceNum { color: var(--vt-accent-ink); font-weight: 800; font-size: 14px; letter-spacing: 0.1em; }
.serviceTitle { font-size: 1.4rem; color: var(--vt-ink); }
.serviceDesc { color: var(--vt-ink-soft); line-height: 1.65; }

.contact { padding: 90px 0; background: var(--vt-surface); }
.contactGrid { display: grid; grid-template-columns: 1fr 1fr; gap: 48px; align-items: center; }
.contactText { color: var(--vt-ink-soft); margin-bottom: 4px; }
.contactPhone { display: inline-block; color: var(--vt-accent-ink); font-size: 1.5rem; font-weight: 800; margin: 8px 0; }
.contactHours { color: var(--vt-ink-soft); }
.socialInline { display: flex; gap: 10px; margin-top: 14px; flex-wrap: wrap; }
.mapWrap {
  border-radius: 20px;
  overflow: hidden;
  min-height: 340px;
  box-shadow: 0 24px 45px -30px var(--vt-accent-ink);
}
.mapWrap iframe { border: 0; width: 100%; height: 100%; min-height: 340px; display: block; }

.footer { background: var(--vt-accent); padding: 70px 0 0; color: var(--vt-on-accent); }
.footerTop { display: flex; align-items: center; justify-content: space-between; gap: 20px; flex-wrap: wrap; padding-bottom: 32px; border-bottom: 1px solid var(--vt-accent-on-deep); }
.footerBrand { display: inline-flex; align-items: center; color: var(--vt-on-accent); font-weight: 700; }
.footerTag { color: var(--vt-on-accent); opacity: 0.85; }
.footerGrid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px; padding: 40px 0; }
.footerCol h4 { color: var(--vt-on-accent); font-size: 1.05rem; margin-bottom: 14px; }
.footerCol ul li,
.footerCol p,
.footerCol a { color: var(--vt-on-accent); opacity: 0.85; font-size: 15px; line-height: 1.7; }
.footerCol a:hover { opacity: 1; }
.footerBottom { border-top: 1px solid var(--vt-accent-on-deep); padding: 24px 0; display: flex; justify-content: space-between; gap: 10px; flex-wrap: wrap; color: var(--vt-on-accent); opacity: 0.75; font-size: 14px; }

.callFab {
  position: fixed;
  right: 24px;
  bottom: 24px;
  z-index: 40;
  display: flex;
  align-items: center;
  gap: 10px;
  background: var(--vt-accent-ink);
  color: var(--vt-on-accent);
  border-radius: 999px;
  padding: 14px 22px;
  font-weight: 700;
  box-shadow: 0 16px 32px -18px var(--vt-accent-ink);
  transition: background 0.2s ease;
}
.callFab:hover { background: var(--vt-accent); color: var(--vt-on-accent); }
.callFabIcon { font-size: 1.2rem; }

@media (max-width: 991px) {
  .nav { position: static; background: var(--vt-surface); padding: 10px 0; }
  .navLinks a { color: var(--vt-ink); }
  .navLinks a:hover { color: var(--vt-accent-ink); }
  .navLinks .navCta { color: var(--vt-on-accent); }
  .hero { min-height: 70vh; padding: 120px 0 110px; }
  .storyGrid { grid-template-columns: 1fr; }
  .storyMedia { max-width: 640px; }
  .servicesGrid { grid-template-columns: 1fr; }
  .serviceCard { grid-template-columns: 170px minmax(0, 1fr); }
  .contactGrid { grid-template-columns: 1fr; }
  .footerGrid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 640px) {
  .container { width: calc(100% - 32px); }
  .topbar .container { justify-content: center; gap: 10px; }
  .topbarPhone { margin-left: 0; }
  .navIn { flex-direction: column; align-items: flex-start; gap: 12px; }
  .navLinks { flex-wrap: wrap; gap: 12px 18px; }
  .heroActions { flex-direction: column; }
  .btnPrimary, .btnGhost { width: 100%; text-align: center; }
  .story { padding: 60px 0; }
  .services { padding: 60px 0; }
  .servicesGrid { grid-template-columns: 1fr; }
  .serviceCard { grid-template-columns: 1fr; }
  .serviceMedia { aspect-ratio: 16 / 10; }
  .serviceImage { height: 100%; }
  .callCard { right: 8px; bottom: 16px; padding: 16px 18px; }
  .contact { padding: 60px 0; }
  .footer { padding-top: 50px; }
  .footerGrid { grid-template-columns: 1fr; }
  .footerBottom { justify-content: center; text-align: center; }
  .callFab { right: 16px; bottom: 16px; padding: 12px 18px; }
}
